def scenes(events, pad=15.0, drive_end=None):
    wins = sorted((max(0, t - pad), t + pad if drive_end is None else min(drive_end, t + pad)) for t in events)
    out = []
    for s, e in wins:
        if out and s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

print(scenes([100.0, 120.0, 400.0, 3590.0], drive_end=3600.0))
